-- Phase 23: appeal/cassation chamber; rulings are append-only.
CREATE TABLE court_review_dockets(id TEXT PRIMARY KEY,appeal_id TEXT NOT NULL REFERENCES court_appeals(id),case_id TEXT NOT NULL REFERENCES court_cases(id),level TEXT NOT NULL CHECK(level IN ('appeal','cassation')),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','decided')),opened_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at TEXT,UNIQUE(appeal_id,level));
CREATE INDEX idx_review_case ON court_review_dockets(case_id,created_at);
CREATE TABLE court_review_rulings(id TEXT PRIMARY KEY,docket_id TEXT NOT NULL UNIQUE REFERENCES court_review_dockets(id),outcome TEXT NOT NULL CHECK(outcome IN ('uphold','reverse','remand')),reasoning TEXT NOT NULL CHECK(length(reasoning) BETWEEN 20 AND 8000),issued_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER review_docket_validate BEFORE INSERT ON court_review_dockets BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM court_appeals a JOIN court_cases c ON c.id=a.case_id WHERE a.id=NEW.appeal_id AND a.case_id=NEW.case_id AND a.status='accepted' AND c.status='judged') THEN RAISE(ABORT,'Invalid appeal') END; END;
CREATE TRIGGER review_ruling_validate BEFORE INSERT ON court_review_rulings BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM court_review_dockets d WHERE d.id=NEW.docket_id AND d.status='open' AND d.opened_by<>NEW.issued_by) THEN RAISE(ABORT,'Invalid review ruling') END; END;
CREATE TRIGGER review_ruling_no_update BEFORE UPDATE ON court_review_rulings BEGIN SELECT RAISE(ABORT,'Rulings are immutable'); END;
CREATE TRIGGER review_ruling_no_delete BEFORE DELETE ON court_review_rulings BEGIN SELECT RAISE(ABORT,'Rulings are immutable'); END;
